set -eu
mkdir -p /opt/market-mcp-deploy/sales-releases/20261014-v1/package /opt/market-mcp-deploy/sales-releases/20261014-v1/backup-api /opt/market-mcp-deploy/sales-releases/20261014-v1/backup-mcp
test "$(sha256sum /opt/market-mcp-deploy/api-releases/20261013-v1/market_data/api_read_models.py | cut -d' ' -f1)" = c8ebcb2c12c7620523f708329439b02b1e2471e6c162baa1da0f734d56b66072
docker exec deploy-new-car-mcp-1 python -c "import hashlib; assert hashlib.sha256(open('/app/mcp/market_data/new_car_server.py','rb').read()).hexdigest()=='c6e266e8dc97eb1096d993ae057b8c756674e69cf14dfba3411e2d8fe12537a8'"
cp /opt/market-mcp-deploy/api-releases/20261013-v1/market_data/api_read_models.py /opt/market-mcp-deploy/sales-releases/20261014-v1/backup-api/
docker cp deploy-new-car-mcp-1:/app/mcp/market_data/new_car_server.py /opt/market-mcp-deploy/sales-releases/20261014-v1/backup-mcp/
printf '%s' '' > /opt/market-mcp-deploy/sales-releases/20261014-v1/package.b64
python3 - <<'PY'
import pathlib,json,gzip,base64
p=pathlib.Path('/opt/market-mcp-deploy/sales-releases/20261014-v1');files=json.loads(gzip.decompress(base64.b64decode((p/'package.b64').read_text())))
for name,text in files.items():(p/'package'/name).write_text(text)
PY
cp /opt/market-mcp-deploy/sales-releases/20261014-v1/package/api_read_models.py /opt/market-mcp-deploy/sales-releases/20261014-v1/package/monthly_sales_read.py /opt/market-mcp-deploy/api-releases/20261013-v1/market_data/
for name in api_read_models.py monthly_sales_read.py new_car_server.py; do docker cp /opt/market-mcp-deploy/sales-releases/20261014-v1/package/$name deploy-new-car-mcp-1:/app/mcp/market_data/$name; done
docker exec market-data-api-20261013 python -c "from pathlib import Path; [compile(p.read_text(),str(p),'exec') for p in [Path('/app/mcp/market_data/api_read_models.py'),Path('/app/mcp/market_data/monthly_sales_read.py')]]"
docker exec deploy-new-car-mcp-1 python -m py_compile /app/mcp/market_data/new_car_server.py /app/mcp/market_data/monthly_sales_read.py
docker restart market-data-api-20261013 deploy-new-car-mcp-1
docker exec market-data-api-20261013 python -c "from market_data.api_read_models import new_car_sales; d=new_car_sales({'model':'理想i8','energy_type':'纯电动'});print('i8_months',len(d['items']),'total',d['total_sales'],'legacy_kept',d['legacy_months_retained']); assert len(d['items'])==15 and d['legacy_months_retained']==3"
